-- IPA 2021-07-25 Q1–24 selected: reviewed adaptations and verified repeats; Q15 and Q18 already linked.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2021-20210725-q01','exam-fe','ビット演算','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問1・改編】1が少なくとも一つあるビット列Aから最も右の1だけを残す。例：00101000→00001000。Aを符号なし2進数とみてB=A−1、C=A XOR Bとした後、AとCに適用する演算はどれか。','[{"id":"a","text":"XOR"},{"id":"b","text":"NAND"},{"id":"c","text":"AND"},{"id":"d","text":"OR"}]','"c"','A XOR (A−1)は最下位の1から右のビットを1にする。元のAとのANDで最下位の1だけが残る。中文：A异或A−1得到最低位的1及其右侧均为1，再与A相与即可保留最低位的1。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q04','exam-fe','条件付き確率','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問4・改編】生産の60%をラインA、40%をラインBが担当し、不良率はAが2%、Bが1%。無作為に選んだ製品が不良品だったとき、A製である確率は何%か。','[{"id":"a","text":"40"},{"id":"b","text":"50"},{"id":"c","text":"60"},{"id":"d","text":"75"}]','"d"','不良品となる確率は0.6×0.02+0.4×0.01=0.016。そのうちA製は0.012なので0.012÷0.016=75%。中文：A的不良占全部产品1.2%，全部不良为1.6%，条件概率为75%。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q06','exam-fe','状態遷移図','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問6・改編】300円の商品を100円硬貨で販売する自動販売機。入力aは100円、bはそれ以外の硬貨で即返却。出力1は販売、0は何もしない。状態S0が開始、二重丸の状態が終了。各選択肢はaの遷移、bの遷移、終了状態の順に示す（表記：現在→次/出力）。適切なものはどれか。','[{"id":"a","text":"a: S0→S1/0、S1→S2/0、S2→S0/1；b: 各状態で同じ状態/0；終了S0"},{"id":"b","text":"a: S0→S1/0、S1→S2/1、S0→S2/1；b: 各状態で同じ状態/0；終了S2"},{"id":"c","text":"a: S0→S1/0、S1→S2/1、S2→S0/0；b: 各状態で同じ状態/0；終了S2"},{"id":"d","text":"a: S0→S0/0、S1→S1/0、S2→S2/1；b: S0→S1/0、S1→S2/0、S2→S0/0；終了S0"}]','"a"','100円2枚でS2、3枚目で販売してS0へ戻る。bはどの状態でも返却し状態を変えない。中文：投入三枚100日元后售货并回到初始状态，其他硬币退回且状态不变。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q09','exam-fe','探索手法','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問9・改編】探索表aはコード順に120380、120381、120520、140140を格納。bは使用頻度順に120381、140140、120520、120380を格納。cはコードから一意に決まる場所に格納する。最も適した探索手法の組合せ（a,b,c）はどれか。','[{"id":"a","text":"二分探索、線形探索、ハッシュ表探索"},{"id":"b","text":"二分探索、ハッシュ表探索、線形探索"},{"id":"c","text":"線形探索、二分探索、ハッシュ表探索"},{"id":"d","text":"線形探索、ハッシュ表探索、二分探索"}]','"a"','整列済みのaは二分探索、頻度順のbは先頭から線形探索、cはハッシュ表探索に適する。中文：排序表适合二分查找，频率顺序表适合线性查找，按键计算位置适合散列查找。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q10','exam-fe','階乗の再帰','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問10・改編】非負整数nの階乗を再帰的に求める。F(0)=1、n>0のときF(n)に入れる式はどれか。','[{"id":"a","text":"n+F(n−1)"},{"id":"b","text":"n−1+F(n)"},{"id":"c","text":"n×F(n−1)"},{"id":"d","text":"(n−1)×F(n)"}]','"c"','n!=n×(n−1)!、0!=1である。中文：阶乘满足n!=n×(n−1)!，0!=1。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q11','exam-fe','MIPS','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問11・改編】700MHzのCPUで、命令の種類ごとの（必要クロック数,出現率）はレジスタ間演算(4,30%)、メモリ・レジスタ間演算(8,60%)、無条件分岐(10,10%)。性能は約何MIPSか。','[{"id":"a","text":"10"},{"id":"b","text":"50"},{"id":"c","text":"70"},{"id":"d","text":"100"}]','"d"','平均CPI=4×0.3+8×0.6+10×0.1=7。700MHz÷7=100 MIPS。中文：平均每条指令7个时钟周期，700MHz÷7=100 MIPS。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q12','exam-fe','内部割込み','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問12・改編】内部割込みに分類されるものはどれか。','[{"id":"a","text":"瞬時停電など電源異常"},{"id":"b","text":"ゼロ除算の実行"},{"id":"c","text":"入出力の完了"},{"id":"d","text":"メモリパリティエラー"}]','"b"','ゼロ除算は命令実行に伴う内部例外。電源、入出力完了、ハードウェアエラーは外部要因。中文：除零由程序指令执行引发，属于内部异常。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q13','exam-fe','USB 3.0','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問13・改編】USB 3.0の説明として適切なものはどれか。','[{"id":"a","text":"4対の信号線を使い最大1Gビット/秒のスループットを持つ"},{"id":"b","text":"ATA仕様をシリアル化したもの"},{"id":"c","text":"音声や映像向けのアイソクロナス転送とブロードキャストを用いる"},{"id":"d","text":"SuperSpeedと呼ばれる5Gビット/秒の転送モードを持つシリアルインタフェース"}]','"d"','USB 3.0のSuperSpeedは規格上5Gbit/sの信号速度を持つ。実効転送速度とは異なる。中文：USB 3.0 SuperSpeed的标称信号速率为5Gbit/s，实际吞吐量会不同。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q14','exam-fe','ストライピング','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問14・改編】データを分散して複数の磁気ディスクに書き込み、入出力の高速化を図る方式はどれか。','[{"id":"a","text":"ストライピング"},{"id":"b","text":"スワッピング"},{"id":"c","text":"ディスクキャッシュ"},{"id":"d","text":"ミラーリング"}]','"a"','ストライピングはデータを複数ディスクへ分散する。ミラーリングは複製を保持する。中文：条带化把数据分布到多块磁盘；镜像则保存副本。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q16','exam-fe','回線の稼働率','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問16・改編】東京〜大阪の直接回線の稼働率0.9、東京〜名古屋の回線0.8。大阪〜名古屋に独立したバックアップ回線を追加し、直接経路又は名古屋経由のどちらかが稼働することで東京〜大阪の稼働率を0.95以上にする。追加回線の最低稼働率はどれか。','[{"id":"a","text":"0.167"},{"id":"b","text":"0.205"},{"id":"c","text":"0.559"},{"id":"d","text":"0.625"}]','"d"','直接経路とバックアップ経路を並列とし、0.9+0.1×0.8×x≥0.95よりx≥0.625。中文：直连不可用的概率为0.1，经名古屋的备用路径可用率为0.8x，解得x至少0.625。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q17','exam-fe','処理時間順スケジューリング','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問17・改編】多重度1で処理時間順の非割込みスケジューリングを行う。ジョブの（到着時刻,単独処理時間）はA=(0,2)、B=(1,4)、C=(2,3)、D=(3,2)、E=(4,1)秒。OSオーバヘッドを無視すると、Bのターンアラウンドタイムは何秒か。','[{"id":"a","text":"8"},{"id":"b","text":"9"},{"id":"c","text":"10"},{"id":"d","text":"11"}]','"d"','実行順はA(0〜2)、C(2〜5)、E(5〜6)、D(6〜8)、B(8〜12)。B到着1秒から完了12秒まで11秒。中文：按照当前已到达任务中处理时间最短者运行，B在12秒完成，周转时间12−1=11秒。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q19','exam-fe','コンパイラの四つ組','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問19・改編】四つ組（演算子,被演算子1,被演算子2,結果）が順に(*,B,C,T1)、(/,T1,D,T2)、(+,A,T2,T3)である。構文解析された式はどれか。T1〜T3は一時変数。','[{"id":"a","text":"A+B*C/D"},{"id":"b","text":"A+B*C/T2"},{"id":"c","text":"B*C+A/D"},{"id":"d","text":"B*C+T1/D"}]','"a"','T1=B×C、T2=T1÷D、T3=A+T2なのでA+B×C÷D。中文：先算B×C，再除以D，最后加A。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q20','exam-fe','7セグメントLED','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問20・改編】アノードコモン型7セグメントLEDの端子a,b,c,d,e,f,g,小数点Dtはそれぞれ出力ポートP0〜P7に対応する。P7が最上位、P0が最下位で、0のとき点灯する。16進92を出力すると点灯する箇所の組はどれか。','[{"id":"a","text":"a,b,c,d,g,Dt"},{"id":"b","text":"b,c,f,g"},{"id":"c","text":"a,c,d,f,g"},{"id":"d","text":"a,c,d,e,f,g,Dt"}]','"c"','92(16)=10010010(2)。0となるP0,P2,P3,P5,P6に対応するa,c,d,f,gが点灯する。中文：92的二进制为10010010，低电平点亮a、c、d、f、g。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q21','exam-fe','フラッシュメモリ','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問21・改編】フラッシュメモリの記述として適切なものはどれか。','[{"id":"a","text":"高速書換え可能でCPUキャッシュに用いられる"},{"id":"b","text":"紫外線で全データを一括消去できる"},{"id":"c","text":"周期的にデータの再書込みが必要"},{"id":"d","text":"ブロック単位で電気的にデータを消去できる"}]','"d"','フラッシュメモリは不揮発性で、一般にブロック単位で電気的に消去する。中文：闪存是非易失性存储器，可按块进行电擦除。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q22','exam-fe','NAND回路','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問22・改編】入力A,Bを1つ目のNAND、C,Dを2つ目のNANDに入力し、その2出力を3つ目のNANDに入力する。出力Xはどれか。・はAND、+はOR。','[{"id":"a","text":"(A+B)・(C+D)"},{"id":"b","text":"A+B+C+D"},{"id":"c","text":"A・B+C・D"},{"id":"d","text":"A・B・C・D"}]','"c"','X=NOT(NOT(A・B)・NOT(C・D))。ド・モルガンの法則でA・B+C・D。中文：对两个NAND输出再次取NAND，依据德摩根定律得到AB+CD。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q23','exam-fe','ニモニックコード','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問23・改編】コードの値からデータの対象物を連想できるコードはどれか。','[{"id":"a","text":"シーケンスコード"},{"id":"b","text":"デシマルコード"},{"id":"c","text":"ニモニックコード"},{"id":"d","text":"ブロックコード"}]','"c"','ニモニックコードは意味や名称を想起しやすい文字などを使う。中文：助记码利用容易联想到对象含义或名称的字符。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q24','exam-fe','PCMデータ量','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問24・改編】60分のモノラル音声を標本化周波数44.1kHz、量子化16ビットのPCMで非圧縮で記録する。データ量はおよそ何Mバイトか。','[{"id":"a","text":"80"},{"id":"b","text":"160"},{"id":"c","text":"320"},{"id":"d","text":"640"}]','"c"','44100標本/秒×2バイト×3600秒=317,520,000バイトで約320MB。中文：每秒44100个样本，每样本2字节，3600秒约3.175亿字节，即约320MB。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption');
